// 1. طبقة النقل: OkHttp Client مع المعترضات وإعدادات المهلة
val okHttpClient = OkHttpClient.Builder()
    .connectTimeout(15, TimeUnit.SECONDS)
    .readTimeout(20, TimeUnit.SECONDS)
    .addInterceptor(AuthHeaderInterceptor(tokenProvider))
    .build()

// 2. طبقة التجريد: واجهة Retrofit المعلنة
interface UserApiService {
    @GET("api/v2/users/{id}")
    suspend fun fetchUserProfile(@Path("id") userId: String): UserNetworkDto
}

// 3. طبقة المستودع: حماية الـ Domain بتحويل الـ DTO لنماذج نقية
class UserRepositoryImpl(
    private val api: UserApiService
) : UserRepository {
    override suspend fun getUser(id: String): Result<UserDomainModel> = runCatching {
        api.fetchUserProfile(id).toDomain()
    }
}
