DAT-06.walkthrough_ar:
بناء متكامل يجمع المكونات الخمسة في Room:
```kotlin
// 1. Entity
@Entity(tableName = "cart_items")
data class CartItemEntity(
    @PrimaryKey val id: String,
    val quantity: Int
)

// 2. DAO + 3. Transaction + 5. Flow Query
@Dao
interface CartDao {
    @Query("SELECT * FROM cart_items")
    fun observeCart(): Flow<List<CartItemEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertItem(item: CartItemEntity)

    @Query("DELETE FROM cart_items")
    suspend fun clearCart()

    @Transaction
    suspend fun replaceCart(items: List<CartItemEntity>) {
        clearCart()
        items.forEach { insertItem(it) }
    }
}

// 4. Migration من الإصدار 1 إلى 2
val MIGRATION_1_2 = object : Migration(1, 2) {
    override fun migrate(db: SupportSQLiteDatabase) {
        db.execSQL("ALTER TABLE cart_items ADD COLUMN notes TEXT DEFAULT '' NOT NULL")
    }
}
```

DAT-07.walkthrough_ar:
بنية تطبيق Offline-First باستخدام Room و WorkManager:
```kotlin
// 1. الكيان المحلي مع حالة المزامنة
@Entity(tableName = "tasks")
data class TaskEntity(
    @PrimaryKey val id: String,
    val title: String,
    val syncStatus: SyncStatus = SyncStatus.SYNCED
)

// 2. المستودع يربط الشاشة بالقاعدة المحلية ويسجل المزامنة في الخلفية
class TaskRepository(
    private val dao: TaskDao,
    private val workManager: WorkManager
) {
    val tasks: Flow<List<Task>> = dao.observeTasks().map { it.toDomain() }

    suspend fun addTask(title: String) {
        val task = TaskEntity(UUID.randomUUID().toString(), title, SyncStatus.PENDING)
        dao.insert(task)
        workManager.enqueue(OneTimeWorkRequestBuilder<SyncWorker>().build())
    }
}
```
